apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{app_name}}
  namespace: {{namespace}}
spec:
  replicas: {{replicas}}
  selector:
    matchLabels:
      app: {{app_name}}
  template:
    metadata:
      labels:
        app: {{app_name}}
    spec:
      containers:
        - name: {{app_name}}
          image: {{image}}
          ports:
            - containerPort: {{container_port}}
          resources:
            requests:
              cpu: 100m
              memory: 128Mi
            limits:
              cpu: 500m
              memory: 512Mi
          readinessProbe:
            httpGet:
              path: /healthz
              port: {{container_port}}
---
apiVersion: v1
kind: Service
metadata:
  name: {{app_name}}
  namespace: {{namespace}}
spec:
  selector:
    app: {{app_name}}
  ports:
    - port: {{service_port}}
      targetPort: {{container_port}}
  type: ClusterIP
